mapper.codeEditorJavascript:
const MONTHS=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const titles=(input.sheets||[]).map(s=>String((s.properties||{}).title||'').trim());
const nowIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const tabs=[];
for(const off of [0,-1,1,-2,-3]){ const d=new Date(nowIL.getFullYear(),nowIL.getMonth()+off,1); const t=MONTHS[d.getMonth()]+' '+d.getFullYear(); if(titles.includes(t)) tabs.push(t); }
const q=s=>"'"+s+"'";
const filters=tabs.map(t=>({a1Range:q(t)+'!A1:Z1500'}));
filters.push({a1Range:"'יעדים'!A2:U200"});
filters.push({a1Range:"'פערים'!A1:G4000"});
filters.push({a1Range:"'הגדרות'!A1:H40"});
filters.push({a1Range:"'בקרה יומית'!A1:A1000"});
filters.push({a1Range:"'BUYME לפי נציג'!AU1:BJ1500"});
filters.push({a1Range:"'מעקב ניתוקים'!A1:L3000"});
if(titles.includes('ניתוקים')) filters.push({a1Range:"'ניתוקים'!A1:M5000"});
filters.push({a1Range:"'הגדרות'!N1:Q400"});
const colorQs=tabs.map(t=>'ranges='+encodeURIComponent(q(t)+'!C1:C1500')).join('&')
  +'&fields='+encodeURIComponent('sheets(properties(title),data(startRow,rowData(values(effectiveFormat(backgroundColor)))))');
return {tabs: JSON.stringify(tabs), tabCount: tabs.length,
  readBody: JSON.stringify({dataFilters:filters, valueRenderOption:'FORMATTED_VALUE'}),
  colorUrl: 'spreadsheets/12NkSDD2emzTYb4n5Zt5P9aLdEcgtrIGelZCKRoU7dZI?'+colorQs};

const DBG={};
const MONTHS={'ינואר':1,'פברואר':2,'מרץ':3,'אפריל':4,'מאי':5,'יוני':6,'יולי':7,'אוגוסט':8,'ספטמבר':9,'אוקטובר':10,'נובמבר':11,'דצמבר':12};
const arr=v=>{ if(typeof v==='string'){ try{return JSON.parse(v);}catch(e){return [];} } return Array.isArray(v)?v:[]; };
const norm=s=>String(s==null?'':s).replace(/\s+/g,' ').trim();
const digits=s=>String(s==null?'':s).replace(/\D/g,'');
const dkey=s=>{const m=norm(s).match(/(\d{1,2})\s+(\S+)\s+(\d{4})/); if(!m) return 0; const mon=MONTHS[m[2]]; if(!mon) return 0; return (+m[3])*10000+mon*100+(+m[1]);};
const kOf=d=>d.getFullYear()*10000+(d.getMonth()+1)*100+d.getDate();
const iso=d=>d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2);
const ddmm=k=>{const s=String(k); return (+s.slice(6))+'/'+(+s.slice(4,6));};
const short=w=>{w=norm(w); if(/סיב יס/.test(w)) return w.replace('סיב יס','סיב'); return w;};
const nowIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const today=new Date(nowIL.getFullYear(),nowIL.getMonth(),nowIL.getDate());
const todayK=kOf(today), todayIso=iso(today);
const add=(d,n)=>new Date(d.getFullYear(),d.getMonth(),d.getDate()+n);
let prev=add(today,-1); if(prev.getDay()===6) prev=add(prev,-1);
const prevK=kOf(prev);
const nextKeys=[]; let nx=add(today,1); if(nx.getDay()===6) nx=add(nx,1); nextKeys.push(kOf(nx));
if(today.getDay()===4) nextKeys.push(kOf(add(today,3)));
const vr=arr(input.vr).map(v=>(v&&v.valueRange)||v||{}); const tabs=arr(input.tabs).map(norm); const tabCount=tabs.length;
const byName=n=>{ const x=vr.find(v=>{ const r=norm(v.range).replace(/^'/,''); return r.startsWith(n+"'!")||r.startsWith(n+'!'); }); return (x&&x.values)||[]; };
const colorSheets=arr(input.colors);
const isGreen=c=>{ if(!c) return false; const r=c.red||0,g=c.green||0,b=c.blue||0; return g>r+0.08 && g>b+0.15 && g<0.95; };
const isRed=c=>{ if(!c) return false; const r=c.red||0,g=c.green||0,b=c.blue||0; return r>0.8 && g<0.6 && b<0.6; };
const ALIAS0={'אוסי':'אוסי גיאן','אופק פ':'אופק','דוד':'דוד חי','איתמר':'איתמר ששון'};
const deals=[];
const MN0=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const curTab0=tabs.indexOf(MN0[nowIL.getMonth()]+' '+nowIL.getFullYear());
const prevM0=new Date(nowIL.getFullYear(),nowIL.getMonth()-1,1); const prevTab0=tabs.indexOf(MN0[prevM0.getMonth()]+' '+prevM0.getFullYear());
// fallen / cancelled this month (09/11/2026): one message to the rep, explanation goes to the 'הסבר נציג' column of the month tab
const fallen=[]; let explCol=-1;
for(let t=0;t<tabCount;t++){
  const rows=byName(tabs[t]);
  const hN=(rows[0]||[]).map(norm).findIndex(x=>x.startsWith('הערות')); const iN=hN>=0?hN:17;
  const hE=(rows[0]||[]).map(norm).findIndex(x=>x.startsWith('הסבר נציג'));
  if(t===curTab0) explCol=hE;
  const fallTab=(t===curTab0||t===prevTab0)&&hE>=0;
  const cs=colorSheets.find(x=>norm((x.properties||{}).title)===tabs[t] && (x.data||[]).length)||{}; const data=((cs.data||[])[0])||{}; const start=data.startRow||0; const rd=data.rowData||[];
  rows.forEach((r,i)=>{
    if(i===0||!r) return;
    const rep=norm(r[7]); const name=norm(r[2]); if(!rep||!name) return;
    const note=norm(r[iN]);
    const cell=((rd[i-start]||{}).values||[])[0]||{};
    const bg=(cell.effectiveFormat||{}).backgroundColor;
    const cancelled=/בוטל|ביטול|ביטל|לא מעוניין/.test(note);
    if(fallTab && (cancelled||isRed(bg))){ const ev=norm(r[hE]); const mk=ev.match(/^⏳\D*(\d{1,2}\/\d{1,2}).*?הודעות\s*(\d+)/);
      if((!ev&&t===curTab0)||mk) fallen.push({rep:ALIAS0[rep]||rep, name, phone:norm(r[3]), num:digits(r[6]), row:i+1, tab:t, col:hE, cnt:mk?+mk[2]:0, last:mk?mk[1]:'', why:cancelled?'בוטל':'ההתקנה נפלה'}); }
    if(cancelled) return;
    deals.push({tab:t, rep, name, phone:norm(r[3]), inst:dkey(r[4]), slot:norm(r[5]), num:digits(r[6]),
      sale:dkey(r[1]), what:norm(r[10]), pkg:norm(r[11]).replace(/\D/g,''), note, green:isGreen(bg), red:isRed(bg)});
  });
}
DBG.perTab=tabs.map((t,i)=>{const ds=deals.filter(d=>d.tab===i); return t+':'+ds.length+'/'+ds.filter(d=>d.green).length;});
const targets=byName('יעדים'); const gaps=byName('פערים'); const settings=byName('הגדרות'); const control=byName('בקרה יומית');
const ALIAS={'אוסי':'אוסי גיאן','אופק פ':'אופק','דוד':'דוד חי','איתמר':'איתמר ששון'};
deals.forEach(d=>{ if(ALIAS[d.rep]) d.rep=ALIAS[d.rep]; });
// month tabs may hold a short name ('שילת') while 'יעדים' holds the full one ('שילת חלפה'): map by unique first name (17/11/2026)
{ const tn=targets.map(r=>norm((r||[])[0])).filter(Boolean);
  deals.forEach(d=>{ if(tn.includes(d.rep)) return; const cand=tn.filter(n=>n.split(' ')[0]===d.rep||d.rep.split(' ')[0]===n); if(cand.length===1) d.rep=cand[0]; }); }
// first sale date per rep (fallback proxy for start of work) -> rookie message only for first 10 working days
const firstSale={}; deals.forEach(d=>{ if(d.sale && (!firstSale[d.rep]||d.sale<firstSale[d.rep])) firstSale[d.rep]=d.sale; });
const wdSince=k=>{ if(!k) return 0; const s=String(k); let c=0; for(let x=new Date(+s.slice(0,4),+s.slice(4,6)-1,+s.slice(6)); x<today; x=add(x,1)){ if(x.getDay()<5) c++; } return c; };
// disconnects (09/11/2026): every open disconnect without a rep answer in 'ניתוקים' gets a separate daily message until answered
const phoneByNum={}; deals.forEach(d=>{ if(d.num && d.phone && !phoneByNum[d.num]) phoneByNum[d.num]=d.phone; });
const repNames=targets.map(r=>norm((r||[])[0])).filter(Boolean);
const resolveRep=c=>{ c=norm(c); if(ALIAS[c]) c=ALIAS[c]; if(!c) return ''; if(repNames.includes(c)) return c;
  const cand=repNames.filter(n=>n.split(' ')[0]===c||c.split(' ')[0]===n); return cand.length===1?cand[0]:''; };
const dtab=byName('ניתוקים');
const dRows={}; dtab.forEach((r,i)=>{ const n=digits((r||[])[1]); if(n.length>=6) dRows[n]={row:i+1,cnt:Number(norm(r[7]))||0,last:norm(r[8]),stat:norm(r[9]),ans:norm(r[10])}; });
const pad2=n=>('0'+n).slice(-2); const todayDM=pad2(today.getDate())+'/'+pad2(today.getMonth()+1); const todayTxt=todayDM+'/'+today.getFullYear();
const seenMin=iso(add(today,-5));
const MAXMSG=4; // first message + 3 reminders (Steve 09/11/2026)
const disc={}; const dWrites=[]; const writes0=dWrites;
byName('מעקב ניתוקים').forEach((r,i)=>{ if(i===0||!r) return;
  const num=digits(r[0]); if(num.length<6) return;
  if(norm(r[9])!=='ניתוק פתוח') return; const first=norm(r[7]); if(first<'2026-11-01') return; if(norm(r[8])<seenMin) return;
  const ex=dRows[num];
  if(ex){ if(ex.ans) return; if(ex.last===todayTxt) return;
    if(ex.cnt>=MAXMSG){ if(!ex.stat) dWrites.push({range:"'ניתוקים'!J"+ex.row, values:[['לא ענה אחרי 3 תזכורות']]}); return; } }
  const rep=resolveRep(r[2]); if(!rep) return;
  (disc[rep]=disc[rep]||[]).push({name:norm(r[1]), num, phone:phoneByNum[num]||'', open:norm(r[5]), days:norm(r[6]), first, ex}); });
Object.keys(disc).forEach(k=>disc[k].sort((a,b)=>a.first.localeCompare(b.first)||a.num.localeCompare(b.num)));
DBG.disc=Object.keys(disc).map(k=>k+':'+disc[k].length).join(', ');
const curMonthName=MN0[nowIL.getMonth()]+' '+nowIL.getFullYear();
let dNext=dtab.length+1; const dHeader='ניתוקים – '+curMonthName; let dNeedHeader=!dtab.some(r=>norm((r||[])[0])===dHeader);
if(!dtab.length){ dWrites.push({range:"'ניתוקים'!A1:M1", values:[['חודש','מספר לקוח','שם לקוח','נייד','נציג','תאריך פתיחת ניתוק','ימים מאקטיבציה','הודעות שנשלחו','הודעה אחרונה','שומר?','תשובת הנציג','תאריך תשובה','מס\' בהודעה']]}); dNext=2; }
const colL=n=>{ let s=''; n++; while(n>0){ const m=(n-1)%26; s=String.fromCharCode(65+m)+s; n=Math.floor((n-1)/26); } return s; };
const cell=(f)=>"'"+tabs[f.tab]+"'!"+colL(f.col)+f.row;
const fall={};
fallen.forEach(f=>{ if(f.last===todayDM) return;
  if(f.cnt>=MAXMSG){ writes0.push({range:cell(f), values:[['❌ הנציג לא ענה אחרי 3 תזכורות']]}); return; }
  const rep=resolveRep(f.rep); if(!rep) return; (fall[rep]=fall[rep]||[]).push(f); });
Object.keys(fall).forEach(k=>fall[k].sort((a,b)=>a.num.localeCompare(b.num)||a.row-b.row));
DBG.fall=Object.keys(fall).map(k=>k+':'+fall[k].length).join(', ')+(explCol<0?' | no explanation column':'');
const MN=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const curTab=tabs.indexOf(MN[nowIL.getMonth()]+' '+nowIL.getFullYear());
const cnt={};
deals.forEach(d=>{ if(d.tab!==curTab||d.red) return; const c=cnt[d.rep]=cnt[d.rep]||{s:0,a:0}; c.s++; if(d.green) c.a++; });
const s1=settings[1]||[]; const G2=Number(norm(s1[6]))||0;
const writes=[];
if(curTab>=0) targets.forEach((r,i)=>{ const n=norm((r||[])[0]); if(!n) return; const c=cnt[n]||{s:0,a:0}; writes.push({range:"'יעדים'!D"+(i+2),values:[[c.s]]}); writes.push({range:"'יעדים'!M"+(i+2),values:[[c.a]]}); });
DBG.counts=Object.keys(cnt).map(k=>k+':'+cnt[k].s+'/'+cnt[k].a).join(', ');
const excl=new Set(); let limit=0.25;
settings.forEach((r,i)=>{ if(i===0||!r) return;
  const d=norm(r[2]).match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/); if(d) excl.add((+d[3])*10000+(+d[2])*100+(+d[1]));
  const l=norm(r[4]).match(/(\d+(?:\.\d+)?)\s*%/); if(l) limit=(+l[1])/100; });
const fresh=control.some(r=>norm((r||[])[0])===todayIso);
// "לא חתם" = ONLY yes's emailed "דוח שגויים" (Steve 15/11/2026). Coral's notes are never used for this.
// The list is copied every morning to 'הגדרות'!N1:Q by a Claude task: N2 = report date-time, customer numbers from N4.
// No report from today -> nobody is flagged as unsigned.
const unsignedSet=new Set(); let unsignedFresh=false;
{ const ux=vr.find(v=>/!\$?N\$?1(:|$)/.test(norm(v.range))); const ur=(ux&&ux.values)||[];
  const um=norm((ur[1]||[])[0]).match(/(\d{4})-(\d{2})-(\d{2})/);
  unsignedFresh=!!um && ((+um[1])*10000+(+um[2])*100+(+um[3]))===todayK;
  if(unsignedFresh) ur.slice(3).forEach(r=>{ const n=digits((r||[])[0]); if(n.length>=6) unsignedSet.add(n); }); }
DBG.unsigned=(unsignedFresh?'today ':'NO REPORT TODAY ')+unsignedSet.size;
// shikuf status from the automatic shikuf bot report (Sharky is no longer used, 09/11/2026)
const shik={};
arr(input.sharky).forEach(r=>{ if(!r) return; const n=digits(r[0]); if(n.length<6) return; const st=norm(r[7]); if(st) shik[n]=st.startsWith('✅'); });
const share={}; let co179=0, coTot=0;
// 179 quota: by installation-coordination month (the month tab), counting every non-cancelled deal WITH an installation date, installed or not (no date = not coordinated yet, 17/11/2026)
deals.forEach(d=>{ if(d.tab!==0||d.red||!d.inst) return; if(!['179','199','209'].includes(d.pkg)) return; if(excl.has(d.sale)) return;
  const s=share[d.rep]=share[d.rep]||{a:0,t:0}; s.t++; coTot++; if(d.pkg==='179'){s.a++; co179++;} });
DBG.share=Object.keys(share).map(k=>k+':'+share[k].a+'/'+share[k].t).join(', ');
// BUYME quota: 179 + yes vouchers above 120 count together (limit in 'BUYME לפי נציג'!BJ15)
const buy=byName('BUYME לפי נציג'); let qLimit=0.4;
{ const qr=(buy[14]||[])[15]; const qm=norm(qr).match(/(\d+(?:\.\d+)?)\s*%/); if(qm) qLimit=(+qm[1])/100; else if(Number(qr)>0&&Number(qr)<=1) qLimit=Number(qr); }
const pn=s=>digits(s).replace(/^972/,'').replace(/^0+/,'');
const dealByPhone={}; deals.forEach(d=>{ if(d.tab!==0) return; const k=pn(d.phone); if(k) dealByPhone[k]=d; });
const curMonth=MN[nowIL.getMonth()]+' '+nowIL.getFullYear();
const vouch={}, dbl={};
// BUYME: from Coral's report (month = report installation/coordination date); counted as soon as coordinated, installed or not
buy.forEach((r,i)=>{ if(i===0||!r) return;
  if(norm(r[8])!==curMonth) return;
  const amt=Number(digits(String(r[9]).split('.')[0]))||0; if(amt<=120) return;
  const d=dealByPhone[pn(r[1])];
  if(d && d.pkg==='179'){ if(d.red||excl.has(d.sale)) return; dbl[d.rep]=(dbl[d.rep]||0)+1; return; }
  if(norm(r[4])!=='') return;
  let rep;
  if(d){ if(d.red) return; if(!['199','209'].includes(d.pkg)) return; if(excl.has(d.sale)) return; rep=d.rep; }
  else { const k=dkey(r[2]); if(!k) return; rep=norm(r[10]); }
  if(!rep) return; vouch[rep]=(vouch[rep]||0)+1; });
DBG.vouch=Object.keys(vouch).map(k=>k+':'+vouch[k]).join(', ');
DBG.dbl=Object.keys(dbl).map(k=>k+':'+dbl[k]).join(', ');

const changed={};
gaps.forEach((r,i)=>{ if(i===0||!r) return;
  if(norm(r[0])!==todayIso) return; if(!/אוקטב בלי אינטרנט/.test(norm(r[1]))) return; if(norm(r[6])==='כן') return;
  const rep=norm(r[4]).replace(/\s*\(.*\)\s*$/,''); (changed[rep]=changed[rep]||[]).push(norm(r[3])||norm(r[2])); });
DBG.changed=Object.keys(changed).join(',');
const CAP=8;
const list=(items,fmt)=>{ const out=items.slice(0,CAP).map(fmt); if(items.length>CAP) out.push('• ועוד '+(items.length-CAP)); return out.join('\n'); };
const bySlot=(a,b)=>(a.inst-b.inst)||a.slot.localeCompare(b.slot);
const jokes=['הקפה כבר מוכן, הלקוחות עוד לא יודעים מה מחכה להם','לקוח שאומר "אני אחשוב על זה" עוד לא שמע את ההצעה השנייה 😉','הטלפון לא מחייג לבד... עדיין','כל "לא" מקרב ל"כן". סטטיסטית זה מוכח (בערך)','היום הופכים "אני מרוצה מהספק שלי" ל"איך לא הכרתי אתכם קודם?"','הסיב מהיר, אבל העסקה הבאה צריכה להיות עוד יותר מהירה','ממיר אחד לסלון, ממיר אחד לחדר, ועסקה אחת ללוח','מי שמחייג ראשון סוגר ראשון. מי שמחייג אחרון סוגר בהפסקת צהריים','תחייכו בשיחה, שומעים את זה גם בטלפון','הלקוח עוד לא יודע שהיום הוא מתחבר לסיב. בואו נספר לו','אם הלקוח אומר "תתקשרו מחר", מזל שגם מחר אנחנו פה 😏','אין לקוח קשה, יש לקוח שעוד לא דיבר איתנו','המשפט הכי יפה בעברית: "בואו נתאם התקנה"','אוזניות על הראש, חיוך על הפנים, יעד בעיניים','היום לא מוכרים טלוויזיה, מוכרים ערבי סדרות על הספה'];
const rookieJokes=['היי טירון, ברוך הבא לצבא של יס. פה המדים זה אוזניות והנשק זה חייגן 🎧','טירון, תזכור: הלקוח לא יודע שאתה חדש. אל תספר לו 🤫','היי טירון חחחח, הוותיקים טוענים שגם הם היו פעם חדשים. אנחנו לא מאמינים להם','היי טירון, היעד שלך 10. זה פחות מכמה פעמים הוותיקים יוצאים לקפה ביום','טירון, העסקה הראשונה היא כמו הקפה של הבוקר. אחרי שהיא נכנסת הכל נראה אחרת','היי טירון, שמענו שאתמול אמרת "שלום, מדבר..." ושכחת איך קוראים לך. קורה לכולם 🙈','טירון! היום אין מסדר בוקר, יש רק מסדר עסקאות','היי טירון, עוד כמה עסקאות ומורידים לך את גלגלי העזר','טירון, בצבא סופרים ימים לשחרור. פה סופרים עסקאות ליעד','היי טירון חחחח, תחייג כאילו הוותיקים מקשיבים לך. כי הם באמת מקשיבים 👀'];
const dayIdx=Math.floor((Date.now()+3*3600000)/86400000);
const joke=jokes[dayIdx%jokes.length];
let rookieN=0;
const items=[]; const preview=[];
const tag=x=>x.cnt>0?' (תזכורת '+x.cnt+' מתוך 3)':' (חדש)';
const discMsg=(first,dc)=>{
  const lines=dc.map((d,i)=>{ const o=norm(d.open).match(/^(\d{1,2})\/(\d{1,2})/); const od=o?(+o[1])+'/'+(+o[2]):'';
    return (i+1)+'. '+d.name+(d.phone?' '+d.phone:' | מס\' לקוח '+d.num)+(od?' | נפתח '+od:'')+tag({cnt:d.ex?d.ex.cnt:0}); });
